SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);Alarm(300);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach(root cat "inputs/fast_full_aut_hash_m3_18_root.m");k:=GF(7);X:=MDX11(3,18,k);F,mp:=AlgorithmicFunctionField(FunctionField(Curve(X)));B:=BaseField(F);PK:=PolynomialRing(k);O:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);d4:=eval Read(root cat "paired_p7_degree4_data.m");K<z>:=ext<k|PK!d4[3]>;out:=[* *];
function DR(a)return B!(PK!a[1])/(B!(PK!a[2]));end function;function DF(a)return F![DR(c):c in a];end function;
for which in[12,17]do a:=eval Read(root cat "relative_quartic_"cat IntegerToString(which)cat".m");pd:=a[4];OO:=pd[2]eq 1 select O else OI;I:=ideal<OO|[DF(c):c in pd[3]]>;assert IsPrime(I);N:=Place(I);assert Degree(N)eq 4;bm:=hom<B->F|DF(a[5][2])>;h:=hom<F->F|bm,DF(a[5][1])>;coords:=[mp(f):f in X`_coordinates];assert &and[Valuation(f,N)ge 0 and Valuation(h(f),N)ge 0:f in coords];vals:=[Evaluate(f,N):f in coords];ims:=[Evaluate(h(f),N):f in coords];assert ims eq[v^49:v in vals]and ims ne vals;qt:=[Evaluate(PK!v,z):v in d4[5][which]];assert M3EighteenRootKey(vals,K,7,4)eq M3EighteenRootKey(qt,K,7,4);assert #Seqset([[v^(7^j):v in vals]:j in[0..3]])eq 4;Append(~out,[*which,2,M3EighteenRootKey(vals,K,7,4),M3EighteenRootKey(ims,K,7,4),true*]);print "M318_QUARTIC_PHASE_BINDING",which,2,Cputime(tt);end for;Write(root cat "quartic_phase_binding.m",Sprint(out):Overwrite:=true);print "D31B_M318_QUARTIC_PHASE_BINDING_COMPLETE",#out,Cputime(tt);quit;
